This minor micro-optimization creates a 50% performance gain on `qemu_riscv64_smp`.
* skip validating thread pointer in `zephyr_thread_wrapper()` (only called from `pthread_create()`)

Sorry to add yet another rev 😅 - probably can't do a lot of harm at this point though.

```diff
diff --git a/lib/posix/pthread.c b/lib/posix/pthread.c
index c55e824d35..30044420f1 100644
--- a/lib/posix/pthread.c
+++ b/lib/posix/pthread.c
@@ -268,6 +268,7 @@ static void zephyr_thread_wrapper(void *arg1, void *arg2, void *arg3)
        int err;
        int barrier;
        void *(*fun_ptr)(void *arg) = arg2;
+       struct posix_thread *t = CONTAINER_OF(k_current_get(), struct posix_thread, thread);
 
        if (IS_ENABLED(CONFIG_PTHREAD_CREATE_BARRIER)) {
                /* cross the barrier so that pthread_create() can continue */
@@ -276,7 +277,7 @@ static void zephyr_thread_wrapper(void *arg1, void *arg2, void *arg3)
                __ASSERT_NO_MSG(err == 0 || err == PTHREAD_BARRIER_SERIAL_THREAD);
        }
 
-       pthread_exit(fun_ptr(arg1));
+       posix_thread_finalize(t, fun_ptr(arg1));
 
        CODE_UNREACHABLE;
 }
```

