It's because posix threads are non-recursive by default (the "error checking" mutex is an optional feature 😉), so if a posix thread attempts to acquire a mutex that it already holds, it will block indefinitely.
```cpp
#include <pthread.h>
#include <stdio.h>

int main()
{
  int r;
  pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;

  r = pthread_mutex_lock(&m);
  if (r != 0) {
    printf("pthread_mutex_lock() failed: %d\n", r);
  }

  // expected to fail
  r = pthread_mutex_trylock(&m);
  if (r != 0) {
    printf("pthread_mutex_trylock() failed: %d\n", r);
  }

  // expected to hang
  r = pthread_mutex_lock(&m);
  if (r != 0) {
    printf("pthread_mutex_lock() failed: %d\n", r);
  } else {
    printf("pthread_mutex_lock() succeeded!\n");
  }

  // should not get here
  return 0;
}
```
Output:
```shell
./foo 
pthread_mutex_trylock() failed: 16
```

